function isTokenExpired(token) {
  if (!token) {
    return true;
  }

  try {
    const parts = token.split(".");

    if (parts.length !== 3) {
      return true;
    }

    let payload = parts[1]
      .replace(/-/g, "+")
      .replace(/_/g, "/");

    payload += "=".repeat(
      (4 - (payload.length % 4)) % 4
    );

    const decoded = JSON.parse(
      atob(payload)
    );

    const now =
      Math.floor(Date.now() / 1000);

    return (
      !decoded.exp ||
      decoded.exp <= now + 30
    );
  } catch {
    return true;
  }
}

async function ensureCustomerToken() {
  const currentToken =
    pm.environment.get(
      "customerAccessToken"
    );

  if (!isTokenExpired(currentToken)) {
    return;
  }

  const response =
    await pm.sendRequest({
      url:
        `${pm.environment.get(
          "baseUrl"
        )}/api/auth/login`,

      method: "POST",

      header: {
        "Content-Type":
          "application/json"
      },

      body: {
        mode: "raw",

        raw: JSON.stringify({
          email:
            pm.environment.get(
              "customerEmail"
            ),

          password:
            pm.environment.get(
              "customerPassword"
            )
        })
      }
    });

  if (response.code !== 200) {
    throw new Error(
      `Customer login failed: ${response.code}`
    );
  }

  const body = response.json();

  pm.environment.set(
    "customerAccessToken",
    body.data.accessToken
  );
}

await ensureCustomerToken();

